CARDS = {}
for t, digits in LV.items():
    old = json.load(open(os.path.join(R, t + '.json')))
    if any(len(c) > 3 for c in old):
        continue
    assert len(digits) == len(old), (t, len(digits), len(old))
    out = []
    for i, c in enumerate(old):
        q, a = REW.get(t, {}).get(i, (None, None))
        out.append((i, c[0], q or c[1], a or c[2], int(digits[i])))
    CARDS[t] = out

